app/components/button/index.gts.dom:
{{#if @href}}    <a disabled="{{this.disabled}}" class="{{this.buttonClassNames}}" href="{{@href}}" ...attributes>{{yield}}</a>
{{else}}    <button disabled="{{this.disabled}}" class="{{this.buttonClassNames}}" type="button" ...attributes>
        {{yield}}
    </button>
{{/if}}

