app/components/manage-payees/delete-conf.dom:
{{#if @showDeleteConfirmation}}  <div class="modal-payees-deleting">
    <h3>{{t "managePayees.newPayee"}}</h3>
    <em>{{t "managePayees.countTransactionsAreUsingThisPayeeSelectANew" count=@checkedPayeeTransactionCount}}</em>
    <XSelect class="payee-select" @options={{@assignablePayeesWhenDeleting}} @value={{@assignedPayeeWhenDeleting}} @change={{@selectAssignablePayeeWhenDeleting}} />
  </div>
  <div class="modal-payees-deleting-actions">
    <Button class="button-cancel" {{on "click" @cancelDeletePayee}} @variant="secondary">{{t "app.cancel"}}</Button>
    <Button class="button-delete" {{on "click" @deletePayee}} @variant="destructive" @disabled={{@isDeleting}}>
{{#if @isDeleting}}        {{t "app.deleting"}}
{{else}}        {{t "app.delete"}}
{{/if}}    </Button>
  </div>
{{else}}  <div class="modal-payees-deleting-actions">
    {{yield}}
    <Button class="button-delete" {{on "click" @delete}} @variant="destructive" @disabled={{@isDeleting}}>
{{#if @isDeleting}}        {{t "app.deleting"}}
{{else}}{{#if @areMultipleChecked}}        {{t "managePayees.deleteAll"}}
{{else}}        {{t "app.delete"}}
      {{/if}}{{/if}}    </Button>
  </div>
{{/if}}
